type MTRDiscoveryCapabilities uint64

const (
	MTRDiscoveryCapabilitiesUnknown MTRDiscoveryCapabilities = 0
	MTRDiscoveryCapabilitiesNone MTRDiscoveryCapabilities = 0
	MTRDiscoveryCapabilitiesSoftAP MTRDiscoveryCapabilities = 1
	MTRDiscoveryCapabilitiesBLE MTRDiscoveryCapabilities = 2
	MTRDiscoveryCapabilitiesOnNetwork MTRDiscoveryCapabilities = 4
	MTRDiscoveryCapabilitiesAllMask MTRDiscoveryCapabilities = 7
)

func (e MTRDiscoveryCapabilities) String() string {
	var parts []string
	if e&MTRDiscoveryCapabilitiesSoftAP != 0 {
		parts = append(parts, "MTRDiscoveryCapabilitiesSoftAP")
	}
	if e&MTRDiscoveryCapabilitiesBLE != 0 {
		parts = append(parts, "MTRDiscoveryCapabilitiesBLE")
	}
	if e&MTRDiscoveryCapabilitiesOnNetwork != 0 {
		parts = append(parts, "MTRDiscoveryCapabilitiesOnNetwork")
	}
	if e&MTRDiscoveryCapabilitiesAllMask != 0 {
		parts = append(parts, "MTRDiscoveryCapabilitiesAllMask")
	}
	if len(parts) == 0 {
		return "0"
	}
	return strings.Join(parts, "|")
}

