type MTRNetworkCommissioningFeature int64

const (
	MTRNetworkCommissioningFeatureWiFiNetworkInterface MTRNetworkCommissioningFeature = 1
	MTRNetworkCommissioningFeatureThreadNetworkInterface MTRNetworkCommissioningFeature = 2
	MTRNetworkCommissioningFeatureEthernetNetworkInterface MTRNetworkCommissioningFeature = 4
)

func (e MTRNetworkCommissioningFeature) String() string {
	var parts []string
	if e&MTRNetworkCommissioningFeatureWiFiNetworkInterface != 0 {
		parts = append(parts, "MTRNetworkCommissioningFeatureWiFiNetworkInterface")
	}
	if e&MTRNetworkCommissioningFeatureThreadNetworkInterface != 0 {
		parts = append(parts, "MTRNetworkCommissioningFeatureThreadNetworkInterface")
	}
	if e&MTRNetworkCommissioningFeatureEthernetNetworkInterface != 0 {
		parts = append(parts, "MTRNetworkCommissioningFeatureEthernetNetworkInterface")
	}
	if len(parts) == 0 {
		return "0"
	}
	return strings.Join(parts, "|")
}

